// NETTOYAGE du texte extrait du PDF
// Entrée : 1 item { text, numpages } (sortie de "Extraire le texte du PDF")
// Sortie : 1 item { texte } avec un chapitre par ligne ("1. ...", "2. ...")
const { text = '', numpages = 1 } = $input.first().json;
if (!text.trim()) {
  throw new Error("Aucun texte extrait du PDF (PDF vide ou scanné) : rien n'a été indexé.");
}

// Les pages sont séparées par une ligne vide (extraction n8n)
const pages = text.replace(/\r/g, '').split('\n\n')
  .map(p => p.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean));

// 1. En-têtes / pieds de page du navigateur : lignes qui reviennent au BORD de plusieurs pages
//    (3 premières / 3 dernières lignes ; chiffres ignorés pour attraper "1/10", "2/10", la date…).
//    On ne regarde que les bords pour ne jamais supprimer une ligne du livre qui se répète.
const cle = l => l.replace(/\d+/g, '#');
const bords = pages.flatMap(p => [...new Set([...p.slice(0, 3), ...p.slice(-3)])]);
const freq = {};
for (const l of bords) freq[cle(l)] = (freq[cle(l)] ?? 0) + 1;
const estEnTete = (l, i, page) => (i < 3 || i >= page.length - 3) && numpages >= 3 && freq[cle(l)] >= 3 && l.length < 200;
const estParasite = l =>
  /^(https?|file):\/\//i.test(l) ||                  // URL
  /^(page\s*)?\d+\s*(\/|of|sur)\s*\d+$/i.test(l) ||  // "3/10", "Page 3 of 10"
  /^\d+$/.test(l);                                   // numéro de page seul
let lignes = pages.flatMap(p => p.filter((l, i) => !estEnTete(l, i, p) && !estParasite(l)));

// 2. Garder uniquement le livre : du chapitre 1 jusqu'à "THE END" (menu du site, ©, etc. supprimés)
const debut = lignes.findIndex(l => /^1\.( |$)/.test(l));
if (debut === -1) {
  throw new Error("Chapitre 1 introuvable : ce PDF n'est pas le Manuel d'Épictète (rien n'a été indexé).");
}
const fin = lignes.findIndex((l, i) => i > debut && /^THE END$/i.test(l));
lignes = lignes.slice(debut, fin === -1 ? undefined : fin);

// 3. Recoller les lignes coupées : mots coupés par un tiret, puis une ligne par chapitre
const texte = lignes.join('\n')
  .replace(/([a-z])-\n([a-z])/g, '$1-$2')  // "self-\nrestraint" -> "self-restraint" (tiret gardé)
  .replace(/\n(?!\d+\.(?: |\n|$))/g, ' ') // retour à la ligne hors début de chapitre -> espace
  .replace(/^(\d+)\.(?=\S)/gm, '$1. ')      // "12." seul sur sa ligne -> "12. " + texte
  .replace(/ {2,}/g, ' ')
  .trim();

return [{ json: { texte, nb_caracteres: texte.length, nb_pages: numpages } }];

// CHUNKING : 1 chunk par chapitre, les chapitres trop longs sont redécoupés par groupes de phrases
// (le PDF ne conserve pas les paragraphes, on coupe donc entre deux phrases)
const NB_CHAPITRES = 52;  // traduction E. Carter (version MIT)
const MAX_MOTS = 350;

const { texte } = $input.first().json;

// Un nouveau chapitre = une ligne "N. ..." avec N = chapitre précédent + 1
// (un "12. " isolé au milieu du texte ne crée donc pas de faux chapitre)
const chapitres = [];
for (const ligne of texte.split('\n')) {
  const m = ligne.match(/^(\d+)\. ([\s\S]*)$/);
  if (m && Number(m[1]) === chapitres.length + 1) {
    chapitres.push({ chapitre: Number(m[1]), texte: m[2].trim() });
  } else if (chapitres.length) {
    chapitres.at(-1).texte += ' ' + ligne.trim();
  }
}

if (chapitres.length !== NB_CHAPITRES) {
  const suite = chapitres.length && chapitres.length < NB_CHAPITRES
    ? ` : chapitre ${chapitres.length + 1} introuvable après le chapitre ${chapitres.length}`
    : '';
  throw new Error(`${chapitres.length} chapitres trouvés au lieu de ${NB_CHAPITRES}${suite}. Mauvais livre, autre traduction ou PDF mal extrait (rien n'a été indexé).`);
}
const vide = chapitres.find(c => !c.texte);
if (vide) throw new Error(`Chapitre ${vide.chapitre} vide : PDF mal extrait (rien n'a été indexé).`);

const nbMots = s => s.split(/\s+/).filter(Boolean).length;

function decouper(texte) {
  const total = nbMots(texte);
  if (total <= MAX_MOTS) return [texte];
  const cible = total / Math.ceil(total / MAX_MOTS);  // parties de taille équilibrée
  const phrases = texte.match(/[^.!?]+[.!?]+["'’”)\]]*\s*|[^.!?]+$/g) ?? [texte];
  const parties = [];
  let courante = '';
  for (const p of phrases) {
    if (courante && nbMots(courante) + nbMots(p) > cible * 1.15) {
      parties.push(courante.trim());
      courante = '';
    }
    courante += p;
  }
  if (courante.trim()) parties.push(courante.trim());
  return parties;
}

return chapitres.flatMap(c => {
  const parties = decouper(c.texte);
  return parties.map((texte, i) => ({
    json: { chapitre: c.chapitre, partie: i + 1, nb_parties: parties.length, texte },
  }));
});

// AUGMENTATION : métadonnées + en-tête de chapitre ajouté au texte vectorisé
// (l'en-tête aide la recherche sur "chapitre 5" et permet au bot de citer sa source)
const LIVRE = "The Enchiridion (Manuel d'Épictète)";
const AUTEUR = 'Epictetus';
const TRADUCTION = 'Elizabeth Carter (1758)';

return $input.all().map(({ json: c }) => {
  const entete = `Enchiridion – Chapter ${c.chapitre}` + (c.nb_parties > 1 ? ` (part ${c.partie}/${c.nb_parties})` : '');
  return {
    json: {
      texte: `${entete}\n${c.texte}`,
      chapitre: c.chapitre,
      partie: c.partie,
      nb_parties: c.nb_parties,
      livre: LIVRE,
      auteur: AUTEUR,
      traduction: TRADUCTION,
      source: `${AUTEUR}, ${entete}, trans. ${TRADUCTION}`,
      nb_mots: c.texte.split(/\s+/).filter(Boolean).length,
    },
  };
});

// MOTS-CLÉS : ajoute à chaque chunk ses 8 mots les plus importants (colonne mots_cles)
// Méthode : mots de 4 lettres ou plus, hors mots vides, classés par fréquence dans le chunk
// (à égalité : ordre d'apparition). Gratuit, instantané et toujours le même résultat.
const NB_MOTS_CLES = 8;
const MOTS_VIDES = new Set(`
about above after again against also among another anything appear appears because been before
being both cannot could does doing done down each either else even ever every from further have
having hence here into itself just less like made make many more most much must myself neither
never none only other others ought over same shall should since some such than that their theirs
them themselves then there therefore these they thing things this those though through thus till
together under unless until upon very what whatever when whenever where whether which while whom
whose will with within without would your yours yourself yourselves said says whoever thee thou
thy thine hath doth also wherein whereby anyone anybody someone somebody nothing something
everything everyone himself herself instead rather indeed still well word words show shows
shown seem seems another always often perhaps already enough
`.split(/\s+/).filter(Boolean));

return $input.all().map(({ json: c }) => {
  const corps = c.texte.split('\n').slice(1).join(' ');  // sans l'en-tête "Enchiridion – Chapter N"
  const mots = corps.toLowerCase().match(/[a-z]+(?:'[a-z]+)?/g) ?? [];
  const compte = new Map();
  mots.forEach((m, i) => {
    if (m.length < 4 || MOTS_VIDES.has(m) || m.includes("'")) return;
    const e = compte.get(m) ?? { n: 0, premier: i };
    e.n++;
    compte.set(m, e);
  });
  const mots_cles = [...compte.entries()]
    .sort((a, b) => b[1].n - a[1].n || a[1].premier - b[1].premier)
    .slice(0, NB_MOTS_CLES)
    .map(([m]) => m);
  return { json: { ...c, mots_cles } };
});

// PRÉPARER LES EMBEDDINGS : regroupe les chunks en requêtes batchEmbedContents pour l'API Gemini
// (100 textes maximum par appel → 1 seul appel pour nos 56 chunks)
const MODELE = 'models/gemini-embedding-2';  // le même modèle doit servir pour les questions
const PAR_APPEL = 100;

const chunks = $input.all().map(i => i.json);
if (chunks.length === 0) throw new Error('Aucun chunk reçu : rien à indexer.');

const lots = [];
for (let i = 0; i < chunks.length; i += PAR_APPEL) {
  const lot = chunks.slice(i, i + PAR_APPEL);
  lots.push({
    json: {
      modele: MODELE,
      chunks: lot,
      requests: lot.map(c => ({ model: MODELE, content: { parts: [{ text: c.texte }] } })),
    },
  });
}
return lots;

// PRÉPARER LES LIGNES : associe chaque vecteur Gemini à son chunk → 1 seul JSON pour la fonction SQL
// epictete_reindexer, qui vide et réinsère la table dans une seule transaction.
const lignes = [];
$input.all().forEach((reponse, i) => {
  const { chunks } = $('Préparer les embeddings').itemMatching(i).json;
  const vecteurs = reponse.json.embeddings ?? [];
  if (vecteurs.length !== chunks.length) {
    throw new Error(`Gemini a renvoyé ${vecteurs.length} vecteurs pour ${chunks.length} chunks : rien n'a été modifié dans la base.`);
  }
  chunks.forEach((c, j) => lignes.push({
    chapitre: c.chapitre,
    partie: c.partie,
    content: c.texte,
    mots_cles: c.mots_cles,
    metadata: { livre: c.livre, auteur: c.auteur, traduction: c.traduction, source: c.source, nb_mots: c.nb_mots, nb_parties: c.nb_parties },
    embedding: `[${vecteurs[j].values.join(',')}]`,
  }));
});

const dimensions = [...new Set(lignes.map(l => l.embedding.split(',').length))];
if (dimensions.length !== 1) throw new Error(`Vecteurs de tailles différentes (${dimensions.join(', ')}) : rien n'a été modifié.`);

return [{ json: { nb_chunks: lignes.length, dimension: dimensions[0], payload: JSON.stringify(lignes) } }];

// 2. CONTEXT : rassemble la question, la session et les derniers échanges, puis prépare l'appel de ROUTING
// Entrée : lignes de "Context : historique (SQL)" (0 à 3 échanges, du plus ancien au plus récent)
const { chatInput, sessionId } = $('1. Input (chat)').first().json;
const question = String(chatInput ?? '').trim();
const echanges = $input.all().map(i => i.json).filter(e => e.question);
const historique = echanges.length
  ? echanges.map(e => `Utilisateur : ${e.question}\nAssistant : ${e.reponse}`).join('\n\n')
  : '(début de la conversation)';

const CONSIGNES_ROUTING = `Tu es le module de ROUTING d'un chatbot sur le Manuel d'Épictète (The Enchiridion, trad. Elizabeth Carter, 52 chapitres, en anglais).
Analyse la dernière question en tenant compte de l'historique, puis réponds UNIQUEMENT avec ce JSON :
{"route": "livre" | "conversation" | "hors_sujet", "requete": "...", "chapitre": nombre ou null, "langue": "fr" | "en", "reponse_directe": "..."}

- route = "livre" : la question porte sur le contenu du Manuel, sur Épictète ou le stoïcisme tel qu'il est présenté dans le livre, ou demande un chapitre.
- route = "conversation" : salutation, remerciement, question sur toi-même (« bonjour », « merci », « tu sais faire quoi ? »).
- route = "hors_sujet" : tout le reste (actualité, maths, autre livre, code…).
- requete (si route = "livre") : requête de recherche AUTONOME, EN ANGLAIS, avec les mots importants. Résous les références grâce à l'historique (« et le suivant ? » après le chapitre 8 → "Enchiridion – Chapter 9"). Si un chapitre est demandé, commence par "Enchiridion – Chapter N".
- chapitre : le numéro du chapitre demandé explicitement (ou déduit de l'historique), sinon null.
- langue : la langue de la DERNIÈRE question.
- reponse_directe (si route ≠ "livre") : réponse courte et polie dans cette langue. Pour "hors_sujet", explique que tu ne réponds qu'aux questions sur le Manuel d'Épictète.`;

return [{
  json: {
    sessionId,
    question,
    historique,
    corps_routing: {
      systemInstruction: { parts: [{ text: CONSIGNES_ROUTING }] },
      contents: [{ role: 'user', parts: [{ text: `Historique :\n${historique}\n\nDernière question : ${question}` }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json' },
    },
  },
}];

// 3. ROUTING : lit la décision du LLM et la sécurise (une réponse illisible ne doit jamais bloquer le chat)
const ctx = $('2. Context : construire').first().json;
const brut = $input.first().json?.candidates?.[0]?.content?.parts?.map(p => p.text ?? '').join('') ?? '';

let d = {};
try {
  d = JSON.parse(brut.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));  // tolère un bloc ```json
} catch (e) {
  d = {};
}

const ROUTES = ['livre', 'conversation', 'hors_sujet'];
const route = ROUTES.includes(d.route) ? d.route : 'livre';  // en cas de doute : on cherche dans le livre
const chapitre = Number.isInteger(Number(d.chapitre)) && Number(d.chapitre) >= 1 && Number(d.chapitre) <= 52 ? Number(d.chapitre) : null;
const langue = d.langue === 'en' ? 'en' : 'fr';
let requete = String(d.requete ?? '').trim() || ctx.question;
if (chapitre && !/chapter\s+\d+/i.test(requete)) requete = `Enchiridion – Chapter ${chapitre} ${requete}`;

return [{
  json: {
    sessionId: ctx.sessionId,
    question: ctx.question,
    historique: ctx.historique,
    route,
    requete,
    chapitre,
    langue,
    reponse_directe: String(d.reponse_directe ?? '').trim(),
    routing_lisible: Object.keys(d).length > 0,
  },
}];

// 5. RERANKING (préparation) : numérote les candidats de la recherche hybride et demande à Gemini de les noter
const r = $('3. Routing : lire la décision').first().json;
const candidats = $input.all().map(i => i.json).filter(c => c.content);

const CONSIGNES_RERANKING = `Tu es le module de RERANKING d'un chatbot sur le Manuel d'Épictète.
Pour chaque passage, note de 0 à 10 à quel point il aide à répondre à la question (10 = répond directement, 0 = sans rapport).
Réponds UNIQUEMENT avec ce JSON : {"scores": [{"id": <numéro du passage>, "score": <0 à 10>}, ...]} en notant TOUS les passages.`;

const liste = candidats.map((c, i) => `[${i + 1}] (chapitre ${c.chapitre})\n${c.content}`).join('\n\n');

return [{
  json: {
    candidats,
    corps_reranking: {
      systemInstruction: { parts: [{ text: CONSIGNES_RERANKING }] },
      contents: [{ role: 'user', parts: [{ text: `Question : ${r.question}\nRequête de recherche : ${r.requete}\n\nPassages :\n\n${liste || '(aucun)'}` }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json' },
    },
  },
}];

// 5. RERANKING (sélection) : garde les meilleurs passages, puis prépare l'appel de GENERATION
const NB_MAX = 4;     // passages envoyés à la génération
const NOTE_MIN = 5;   // note minimale sur 10

const r = $('3. Routing : lire la décision').first().json;
const { candidats } = $('5. Reranking : préparer').first().json;
const brut = $input.first().json?.candidates?.[0]?.content?.parts?.map(p => p.text ?? '').join('') ?? '';

let notes = null;
try {
  const d = JSON.parse(brut.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));
  notes = new Map((d.scores ?? []).map(s => [Number(s.id), Number(s.score)]));
} catch (e) {
  notes = null;
}

let gardes;
if (notes && notes.size) {
  gardes = candidats
    .map((c, i) => ({ ...c, note: notes.get(i + 1) ?? 0, rang_hybride: i + 1 }))
    .filter(c => c.note >= NOTE_MIN || (r.chapitre && c.chapitre === r.chapitre))  // chapitre demandé : toujours gardé
    .sort((a, b) => (b.chapitre === r.chapitre) - (a.chapitre === r.chapitre) || b.note - a.note || a.rang_hybride - b.rang_hybride)
    .slice(0, NB_MAX);
} else {
  // notation illisible : on se fie à l'ordre de la recherche hybride
  gardes = candidats.slice(0, NB_MAX).map((c, i) => ({ ...c, note: null, rang_hybride: i + 1 }));
}

const CONSIGNES_GENERATION = `Tu es un guide du Manuel d'Épictète (The Enchiridion, traduction d'Elizabeth Carter).
Règles :
1. Réponds UNIQUEMENT à partir des passages fournis. N'utilise jamais tes connaissances générales et n'invente rien.
2. Si les passages ne permettent pas de répondre, dis simplement que tu ne trouves pas cette information dans le Manuel d'Épictète.
3. Réponds en ${r.langue === 'en' ? 'anglais' : 'français'}, de façon claire et concise.
4. Cite tes sources avec le numéro de chapitre, par ex. (Chapitre 5) ou (Chapter 5). Tu peux citer de courts extraits en anglais d'origine, entre guillemets.`;

const passages = gardes.map(c => `--- Chapitre ${c.chapitre}${c.content.includes('(part ') ? `, partie ${c.partie}` : ''}\n${c.content}`).join('\n\n');

return [{
  json: {
    gardes: gardes.map(c => ({ chapitre: c.chapitre, partie: c.partie, note: c.note, rang_hybride: c.rang_hybride })),
    chapitres: [...new Set(gardes.map(c => c.chapitre))],
    corps_generation: {
      systemInstruction: { parts: [{ text: CONSIGNES_GENERATION }] },
      contents: [{ role: 'user', parts: [{ text: `Historique de la conversation :\n${r.historique}\n\nQuestion : ${r.question}\n\nPassages du Manuel :\n\n${passages || '(aucun passage pertinent trouvé)'}` }] }],
      generationConfig: { temperature: 0.2 },
    },
  },
}];

// 6. GENERATION : récupère le texte de Gemini et prépare l'enregistrement de l'échange
const r = $('3. Routing : lire la décision').first().json;
const { chapitres } = $('5. Reranking : garder les meilleurs').first().json;
const texte = ($input.first().json?.candidates?.[0]?.content?.parts ?? []).map(p => p.text ?? '').join('').trim();

const reponse = texte || (r.langue === 'en'
  ? "Sorry, I couldn't generate an answer. Please try again."
  : "Désolé, je n'ai pas pu générer de réponse. Réessaie.");

return [{ json: { sessionId: r.sessionId, question: r.question, reponse, route: r.route, requete: r.requete, chapitres } }];

// RÉPONSE DIRECTE (route "conversation" ou "hors_sujet") : pas de recherche, pas d'appel en plus
const r = $input.first().json;
const PAR_DEFAUT = {
  conversation: {
    fr: "Bonjour ! Je réponds à tes questions sur le Manuel d'Épictète, en citant les chapitres.",
    en: "Hello! I answer your questions about Epictetus' Enchiridion, citing the chapters.",
  },
  hors_sujet: {
    fr: "Je ne réponds qu'aux questions sur le Manuel d'Épictète.",
    en: "I only answer questions about Epictetus' Enchiridion.",
  },
};
const reponse = r.reponse_directe || PAR_DEFAUT[r.route]?.[r.langue] || PAR_DEFAUT.hors_sujet.fr;

return [{ json: { sessionId: r.sessionId, question: r.question, reponse, route: r.route, requete: '', chapitres: [] } }];
